import{_ as n,W as i,s as h,u as d,ah as o,I as l,w as s,Z as t,A as p}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const y=JSON.parse('{"title":"Oh My Zsh 和 Powerlevel10k：天作之合 | LCTT x X-CMD","titleTemplate":false,"description":"Oh My Zsh 和 Powerlevel10k：天作之合 | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Oh My Zsh 和 Powerlevel10k：天作之合 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Oh My Zsh 和 Powerlevel10k：天作之合 | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221227.1 ⭐️⭐️ oh my zsh and powerlevel10k A Match Made in Heaven","title":"Oh My Zsh 和 Powerlevel10k：天作之合","tag":"202301"},"relativePath":"202301/20221227.1 ⭐️⭐️ oh my zsh and powerlevel10k A Match Made in Heaven.md","filePath":"[post].md"}'),r={name:"202301/20221227.1 ⭐️⭐️ oh my zsh and powerlevel10k A Match Made in Heaven.md"};function u(g,e,c,b,v,m){const a=i("Link");return d(),h("div",null,[e[25]||(e[25]=o('<h1 id="oh-my-zsh-和-powerlevel10k-天作之合" tabindex="-1">Oh My Zsh 和 Powerlevel10k：天作之合 <a class="header-anchor" href="#oh-my-zsh-和-powerlevel10k-天作之合" aria-label="Permalink to Oh My Zsh 和 Powerlevel10k：天作之合">​</a></h1><blockquote><p>这是一篇快速而简单的指南，用 Oh My Zsh 和 Powerlevel10k 主题改造你的 Zsh 终端 Shell，使其在 Ubuntu 和其他 Linux 发行版中看起来很酷。</p></blockquote><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/ohp10k.jpg" alt=""></p><p>大多数 Linux 发行版中的默认 Shell 是 Bash。Bash 是一个可靠的和传统的工具。然而，它缺乏一些自定义功能，比如漂亮的颜色、光标支持等等。</p><p>你可以使用另一个 Shell，即 Zsh 来得到更多的设置调整，并帮助你扩展你的 Bash Shell 体验。</p><p>这个简单的指南解释了如何安装 Zsh、Oh My Zsh 并应用 Powerlevel10k 主题。</p><h3 id="oh-my-zsh-和-powerlevel10k-安装和配置指南" tabindex="-1">Oh My Zsh 和 Powerlevel10k 安装和配置指南 <a class="header-anchor" href="#oh-my-zsh-和-powerlevel10k-安装和配置指南" aria-label="Permalink to Oh My Zsh 和 Powerlevel10k 安装和配置指南">​</a></h3><h4 id="_1、安装-zsh-和改变-shell" tabindex="-1">1、安装 Zsh 和改变 Shell <a class="header-anchor" href="#_1、安装-zsh-和改变-shell" aria-label="Permalink to 1、安装 Zsh 和改变 Shell">​</a></h4><p>打开一个终端，使用以下适用于你的发行版的命令安装 Zsh。</p><p>Ubuntu、Debian、Linux Mint 和所有相关的发行版：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install zsh</span></span></code></pre></div><p>Fedora：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo dnf install zsh</span></span></code></pre></div><p>Arch：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pacman -S zsh</span></span></code></pre></div><p>安装完成后，找出 Zsh 的安装路径：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>whereis zsh</span></span></code></pre></div><p>然后使用当前用户的 Zsh 可执行路径改变 Shell。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chsh -s /usr/bin/zsh &lt;用户名 &gt;</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/change-the-shell-for-the-current-user.jpg" alt="改变当前用户的 Shell"></p><p>关闭并再次打开终端。然后你应该看到 Zsh 的首次设置。选择选项 2。它将用一个默认的主题改变你的 Shell 提示符的外观，如下图所示：</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/first-time-setup-for-zsh.jpg" alt="Zsh 的首次设置"></p><h4 id="_2、安装-oh-my-zsh" tabindex="-1">2、安装 Oh My Zsh <a class="header-anchor" href="#_2、安装-oh-my-zsh" aria-label="Permalink to 2、安装 Oh My Zsh">​</a></h4><p>Oh My Zsh 是一套可以进一步定制 Zsh 的脚本。</p>',24)),l("p",null,[e[1]||(e[1]=s("首先，我们将从 GitHub 上下载 Oh My Zsh 脚本来安装它。如果你有 ")),e[2]||(e[2]=l("code",null,"wget",-1)),e[3]||(e[3]=s(" 和 ")),e[4]||(e[4]=l("code",null,"git",-1)),e[5]||(e[5]=s(" 软件包，那就最好了。如果还没有安装，请使用以下命令 ")),t(a,{href:"https://www.debugpoint.com/wget-not-found-error/"},{default:p(()=>e[0]||(e[0]=[s("安装 wget")])),_:1}),e[6]||(e[6]=s(" & git："))]),e[26]||(e[26]=o(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install wget</span></span>
<span class="line"><span>sudo apt install git</span></span></code></pre></div><p>然后用下面的命令安装 Oh My Zsh：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh -c &quot;$(wget -O- https://raw.githubusercontent.com/ohmyzsh/ohmyzsh/master/tools/install.sh)&quot;</span></span></code></pre></div><p>然后你应该看到 Oh My Zsh 及默认主题 Robbyrussell 应用到了你的终端。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/Install-oh-my-zsh-and-default-theme.jpg" alt="安装 Oh My Zsh 和默认主题"></p>`,5)),l("p",null,[e[8]||(e[8]=s("Oh My Zsh 还附带了其他的主题，你可以 ")),t(a,{href:"https://www.debugpoint.com/install-use-zsh/"},{default:p(()=>e[7]||(e[7]=[s("使用这篇指南")])),_:1}),e[9]||(e[9]=s(" 安装它们。然而，在本教程中，我将谈论一个特定的主题，即 Powerlevel10k。"))]),e[27]||(e[27]=o('<h4 id="_3、为-oh-my-zsh-安装-powerlevel10k-主题" tabindex="-1">3、为 Oh My Zsh 安装 Powerlevel10k 主题 <a class="header-anchor" href="#_3、为-oh-my-zsh-安装-powerlevel10k-主题" aria-label="Permalink to 3、为 Oh My Zsh 安装 Powerlevel10k 主题">​</a></h4><p>打开终端，运行以下命令，从 GitHub 上克隆 Powerlevel10k 代码库，并将文件放到 Oh My Zsh 的配置文件夹中。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/romkatv/powerlevel10k.git $ZSH_CUSTOM/themes/powerlevel10k</span></span></code></pre></div><p>用文本编辑器打开 <code>~/.zshrc</code> 文件，将 <code>ZSH_THEME</code> 变量设为 <code>&quot;powerlevel10k/powerlevel10k&quot;</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd ~</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nano .zshrc</span></span></code></pre></div><p>默认情况下，它应该是 Robbyrussell。删除 <code>”robbyrussell&quot;</code>，添加下面的 <code>&quot;powerlevel10k/powerlevel10k&quot;</code>。</p><p>更改后，你的 <code>~/.zshrc</code> 文件应该是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ZSH_THEME=&quot;powerlevel10k/powerlevel10k”</span></span></code></pre></div><p>保存并关闭该文件（<code>CTRL+O</code>、回车和 <code>CTRL+X</code>）。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/change-oh-my-zsh-theme-to-powerlevel10k.jpg" alt="改变 Oh My Zsh 主题为 Powerlevel10k"></p><p>重新启动你的终端，启动首次向导来设置 Powerlevel10k 主题。</p><h4 id="_4、powerleve10k-的首次设置" tabindex="-1">4、Powerleve10k 的首次设置 <a class="header-anchor" href="#_4、powerleve10k-的首次设置" aria-label="Permalink to 4、Powerleve10k 的首次设置">​</a></h4><p>安装后启动终端时，Powerlevel10k 会提示你各种问题以了解你的 Linux 发行版设置。所以，根据你的需要按下键，按照你的口味来定制你的终端。下面是一些问题的例子截图，可以给你一些启发。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/powerlevel10k-wizard1.jpg" alt="Powerlevel10k - wizard1"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/powerlevel10k-wizard-2.jpg" alt="Powerlevel10k - wizard2"></p><p>最后，你可以保存文件，享受你的终端的新面貌。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/After-applying-settings-in-powerlevel10k-zsh-theme.jpg" alt="应用 Powerlevel10k Zsh 主题设置后"></p><p>如果你想再次重启配置向导，运行以下程序。你可以随心所欲地做，次数不限。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p10k configure</span></span></code></pre></div><p>基本设置就这样结束了。如果你想了解更多，请继续阅读。</p><h3 id="更多配置-高级用法" tabindex="-1">更多配置（高级用法） <a class="header-anchor" href="#更多配置-高级用法" aria-label="Permalink to 更多配置（高级用法）">​</a></h3><h4 id="_5、安装-dracula-gnome-终端主题" tabindex="-1">5、安装 Dracula GNOME 终端主题 <a class="header-anchor" href="#_5、安装-dracula-gnome-终端主题" aria-label="Permalink to 5、安装 Dracula GNOME 终端主题">​</a></h4><p>如果你使用的是带有原生终端应用的 GNOME 桌面，你可以试试令人惊叹的 Drakula 主题。要做到这一点，打开一个终端，运行下面的命令来下载该主题：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/dracula/gnome-terminalcd gnome-terminal</span></span></code></pre></div><p>打开 GNOME “终端”应用，进入偏好设置。通过点击 “+” 添加一个新的配置文件，并命名为 “drakula”。然后进入颜色标签，取消勾选 “<ruby>使用系统主题的颜色<rt>use colors from system theme</rt></ruby>” 选项。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/create-a-new-profile-for-terminal.jpg" alt="为终端创建一个新的配置文件"></p><p>回到终端，运行以下程序。当出现提示时，选择你刚才创建的配置文件名称，如上所述。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./install.sh</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/applying-the-drakula-theme-for-gnome-terminal.jpg" alt="为 GNOME “终端”应用 Drakula 主题"></p><p>一旦安装完成，回到偏好设置中，将 Drakula 配置文件标记为默认。</p><h4 id="_6、zsh-的自动补完和语法高亮" tabindex="-1">6、Zsh 的自动补完和语法高亮 <a class="header-anchor" href="#_6、zsh-的自动补完和语法高亮" aria-label="Permalink to 6、Zsh 的自动补完和语法高亮">​</a></h4><p>你可能想试试由社区开发的两个可用于 Zsh 的插件。它们是 zsh-autosuggestions 和 zsh-syntax-highlighting。</p><p>打开终端，运行以下程序，下载 zsh-autosuggestions，并将其放在插件文件夹中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/zsh-users/zsh-autosuggestions.git $ZSH_CUSTOM/plugins/zsh-autosuggestions</span></span></code></pre></div><p>同样地，为语法高亮插件运行以下程序：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/zsh-users/zsh-syntax-highlighting.git $ZSH_CUSTOM/plugins/zsh-syntax-highlighting</span></span></code></pre></div><p>通过文本编辑器打开 <code>~/.zshrc</code>文件（使用以下命令），并找到 <code>plugins=(git)</code> 一行。并将其替换为以下内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nano ~/.zshrc</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins=(git zsh-autosuggestions zsh-syntax-highlighting)</span></span></code></pre></div><p>使用 <code>CTRL+O</code>、回车和 <code>CTRL+X</code> 保存并关闭该文件。</p><p>关闭并打开你的终端。现在，你应该可以使用自动建议和语法高亮了。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to 总结">​</a></h3><p>这样就好了！你现在应该已经在你的系统上安装了 Oh My Zsh 和 Powerlevel10k 主题。你可以根据自己的需要，进一步定制 Powerlevel10k 主题的外观和行为。</p><p>干杯。</p><hr>',46)),l("p",null,[e[11]||(e[11]=s("via: ")),t(a,{href:"https://www.debugpoint.com/oh-my-zsh-powerlevel10k/"},{default:p(()=>e[10]||(e[10]=[s("https://www.debugpoint.com/oh-my-zsh-powerlevel10k/")])),_:1})]),l("p",null,[e[16]||(e[16]=s("作者：")),t(a,{href:"https://www.debugpoint.com/author/admin1/"},{default:p(()=>e[12]||(e[12]=[s("Arindam")])),_:1}),e[17]||(e[17]=s(" 选题：")),t(a,{href:"https://github.com/lkxed"},{default:p(()=>e[13]||(e[13]=[s("lkxed")])),_:1}),e[18]||(e[18]=s(" 译者：")),t(a,{href:"https://github.com/wxy"},{default:p(()=>e[14]||(e[14]=[s("wxy")])),_:1}),e[19]||(e[19]=s(" 校对：")),t(a,{href:"https://github.com/wxy"},{default:p(()=>e[15]||(e[15]=[s("wxy")])),_:1})]),l("p",null,[e[22]||(e[22]=s("本文由 ")),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>e[20]||(e[20]=[s("LCTT")])),_:1}),e[23]||(e[23]=s(" 原创编译，")),t(a,{href:"https://linux.cn/"},{default:p(()=>e[21]||(e[21]=[s("Linux中国")])),_:1}),e[24]||(e[24]=s(" 荣誉推出"))])])}const C=n(r,[["render",u]]);export{y as __pageData,C as default};
